def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Extract move sequences
    my = []
    op = []
    for h in history:
        my.append(h[0])
        op.append(h[1])

    # Tally counts and scores
    cc = cd = dc = dd = 0
    my_score = 0
    op_score = 0
    for i in range(n):
        a = my[i]
        b = op[i]
        if a == 'C':
            if b == 'C':
                cc += 1
                my_score += 3
                op_score += 3
            else:
                cd += 1
                op_score += 5
        else:
            if b == 'C':
                dc += 1
                my_score += 5
            else:
                dd += 1
                my_score += 1
                op_score += 1

    opp_c = cc + cd
    opp_d = dc + dd
    last_op = op[-1]

    # Permanent opponent profile detection
    if opp_d == 0:
        # Always cooperate, but exploit in final rounds
        if n >= 97:
            # Defect on last few rounds for the big payoff
            return 'D'
        return 'C'
    if opp_c == 0:
        # Always defecting: defect back (DD=1 beats CD=0)
        return 'D'

    # Opponent defection ratio
    opp_def_rate = float(opp_d) / float(n)

    # Recent window analysis
    if n >= 12:
        recent = op[-12:]
        recent_def = 0
        for a in recent:
            if a == 'D':
                recent_def += 1
    else:
        recent_def = opp_d

    # Aggressive if opponent is consistently defecting
    if opp_def_rate > 0.5:
        # Try occasional forgiveness to recover if late
        if last_op == 'D':
            if recent_def >= 4:
                return 'D'
            # probe for cooperation recovery
            if rng.random() < 0.1 and n < 90:
                return 'C'
            return 'D'
        else:
            # They just cooperated after lots of defection
            if rng.random() < 0.4:
                return 'C'
            return 'D'

    # Moderately defecting opponent
    if last_op == 'D':
        # Retaliate hard but avoid permanent spiral
        if recent_def >= 3:
            return 'D'
        if n >= 85:
            return 'D'
        # Forgive occasionally to rebuild
        if opp_def_rate < 0.15:
            return 'C'
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    # Last opponent move was C
    # If opponent mostly cooperates, keep cooperating but exploit late
    if opp_def_rate < 0.1:
        if n >= 95:
            return 'D'
        # Rare probe to keep them honest
        if n >= 20 and rng.random() < 0.03:
            return 'D'
        return 'C'

    # Opponent is mixed. Defect if we're being suckered recently
    if n >= 8:
        recent8 = op[-8:]
        r_def = 0
        for a in recent8:
            if a == 'D':
                r_def += 1
        if r_def >= 3:
            if rng.random() < 0.7:
                return 'D'
            return 'C'
        if r_def <= 1:
            # Mostly cooperative recently - exploit opportunity
            if n >= 85:
                return 'D'
            if rng.random() < 0.08:
                return 'D'
            return 'C'
        # mid: punish defection with moderate probability
        if rng.random() < 0.3:
            return 'D'
        return 'C'

    # Early game
    return 'C'
